'use client';

import * as React from 'react';
import { ArrowLeftIcon, type LucideIcon } from 'lucide-react';

import { cn } from '@/lib/utils';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Button, buttonVariants } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Spinner } from '@/components/ui/spinner';
import { focusRingClass } from '@/components/ui/workspace-kit/primitives';
import type { AuthLinkComponent, AuthNotice } from '@/components/ui/auth-pages/types';

/** The link component an `AuthLayout` or `AuthCard` hands down to the links inside it. */
export const AuthLinkContext = React.createContext<AuthLinkComponent | undefined>(undefined);

export function AuthLink({ href, className, children }: { href: string; className?: string; children: React.ReactNode }) {
	const LinkComponent = React.useContext(AuthLinkContext);
	if (LinkComponent) {
		return (
			<LinkComponent className={className} href={href}>
				{children}
			</LinkComponent>
		);
	}
	return (
		<a className={className} href={href}>
			{children}
		</a>
	);
}

/** A quiet footer link, such as "Forgot password?". */
export const mutedLinkClass = cn('cursor-pointer rounded text-muted-foreground hover:text-foreground', focusRingClass);
/** The footer's call to action, such as "Create account". */
export const primaryLinkClass = cn('cursor-pointer rounded font-medium text-primary hover:underline', focusRingClass);
/** A footer sentence with a link in it; long translations wrap instead of widening the card. */
export const footerTextClass = 'text-muted-foreground min-w-0 [overflow-wrap:anywhere]';

const TONE_TILE = {
	primary: 'bg-primary/10 text-primary ring-primary/20',
	success: 'bg-success/10 text-success ring-success/20',
	destructive: 'bg-destructive/10 text-destructive ring-destructive/20',
} as const;

const NOTICE_VARIANT = { info: 'info', success: 'success', error: 'destructive' } as const;

type AuthCardProps = {
	icon: LucideIcon | 'spinner';
	tone?: keyof typeof TONE_TILE;
	title: React.ReactNode;
	description?: React.ReactNode;
	notice?: AuthNotice;
	footer?: React.ReactNode;
	/** The panel's own link component; falls back to the one from `AuthLayout`. */
	linkComponent?: AuthLinkComponent;
	/** Moves focus to the heading on mount, for a state that replaces the one the person was using. */
	focusTitle?: boolean;
	className?: string;
	children?: React.ReactNode;
};

/** The card every auth panel shares: icon tile, heading, description, notice, body, and dashed footer. */
export function AuthCard({
	icon: Icon,
	tone = 'primary',
	title,
	description,
	notice,
	footer,
	linkComponent,
	focusTitle = false,
	className,
	children,
}: AuthCardProps) {
	const inherited = React.useContext(AuthLinkContext);
	const titleRef = React.useRef<HTMLHeadingElement>(null);
	const hasBody = Boolean(notice) || React.Children.toArray(children).length > 0;

	React.useEffect(() => {
		if (focusTitle) titleRef.current?.focus();
	}, [focusTitle]);

	return (
		<AuthLinkContext.Provider value={linkComponent ?? inherited}>
			<Card className={cn('w-full min-w-0 max-w-sm gap-0 border-0 py-0 shadow-card', className)} data-slot="auth-card" variant="flat">
				<CardHeader className={cn('gap-1 px-6 pt-6', hasBody ? 'pb-4' : 'pb-6')}>
					<div className={cn('mb-3 grid size-9 place-items-center rounded-[10px] ring-1 ring-inset', TONE_TILE[tone])}>
						{Icon === 'spinner' ? <Spinner className="size-4" decorative /> : <Icon aria-hidden="true" className="size-4" />}
					</div>
					<CardTitle>
						<h1 className="text-balance text-lg font-medium tracking-tight outline-none" ref={titleRef} tabIndex={focusTitle ? -1 : undefined}>
							{title}
						</h1>
					</CardTitle>
					{description ? <CardDescription className="text-pretty text-[13px]">{description}</CardDescription> : null}
				</CardHeader>
				{hasBody ? (
					<CardContent className="flex min-w-0 flex-col gap-4 px-6 pb-6">
						{notice ? (
							<Alert role={notice.tone === 'error' ? 'alert' : 'status'} variant={NOTICE_VARIANT[notice.tone]}>
								<AlertDescription>{notice.message}</AlertDescription>
							</Alert>
						) : null}
						{children}
					</CardContent>
				) : null}
				{footer ? (
					<CardFooter className="flex flex-wrap items-center justify-between gap-2 border-t border-dashed border-foreground/10 bg-muted/30 px-6 py-3 text-[13px]">
						{footer}
					</CardFooter>
				) : null}
			</Card>
		</AuthLinkContext.Provider>
	);
}

/** The failure a handler answered with. */
export function AuthFailure({ message }: { message?: string }) {
	if (!message) return null;
	return (
		<Alert role="alert" variant="destructive">
			<AlertDescription>{message}</AlertDescription>
		</Alert>
	);
}

/** The full-width submit button, disabled with its pending label while the handler runs. */
export function AuthSubmit({
	pending,
	label,
	pendingLabel,
	disabled = false,
	type = 'submit',
	variant,
	onClick,
}: {
	pending: boolean;
	label: React.ReactNode;
	pendingLabel: React.ReactNode;
	disabled?: boolean;
	type?: 'submit' | 'button';
	variant?: 'default' | 'outline';
	onClick?: () => void;
}) {
	return (
		<Button aria-busy={pending} disabled={pending || disabled} onClick={onClick} type={type} variant={variant} wrap>
			{pending ? <Spinner decorative /> : null}
			{pending ? pendingLabel : label}
		</Button>
	);
}

/** A primary call to action that navigates, such as "Sign in" after a reset. */
export function AuthLinkButton({ href, children }: { href: string; children: React.ReactNode }) {
	return (
		<AuthLink className={cn(buttonVariants({ wrap: true }), 'w-full')} href={href}>
			{children}
		</AuthLink>
	);
}

/** The footer of every panel except sign-in: a ghost link back to sign in. */
export function BackToSignIn({ href }: { href: string }) {
	return (
		<AuthLink className={cn(buttonVariants({ size: 'sm', variant: 'ghost', wrap: true }), '-my-1')} href={href}>
			<ArrowLeftIcon aria-hidden="true" className="rtl:-scale-x-100" data-icon="inline-start" />
			Back to sign in
		</AuthLink>
	);
}

/** The address an email went to, kept left to right inside any sentence. */
export function EmailAddress({ email }: { email: string }) {
	return <bdi className="text-foreground font-medium [overflow-wrap:anywhere]">{email}</bdi>;
}

'use client';

import * as React from 'react';

import { cn } from '@/lib/utils';
import { focusRingClass } from '@/components/ui/workspace-kit/primitives';
import { AuthLink, AuthLinkContext } from '@/components/ui/auth-pages/auth-card';
import type { AuthBrand, AuthLayoutProps } from '@/components/ui/auth-pages/types';

const brandClass = 'flex min-w-0 max-w-full items-center justify-center gap-2.5 text-foreground';

function BrandMark({ brand }: { brand: AuthBrand }) {
	const content = (
		<>
			{brand.logo ? (
				<span aria-hidden="true" className="grid size-8 shrink-0 place-items-center overflow-hidden rounded-[10px] [&>img]:size-full [&>img]:object-cover [&>svg]:size-5">
					{brand.logo}
				</span>
			) : null}
			<span className="min-w-0 text-pretty text-base font-semibold tracking-tight [overflow-wrap:anywhere]" dir="auto">
				{brand.name}
			</span>
		</>
	);

	if (!brand.href) return <div className={brandClass}>{content}</div>;
	return (
		<AuthLink
			className={cn(brandClass, 'rounded-md hover:opacity-80', focusRingClass)}
			href={brand.href}
		>
			{content}
		</AuthLink>
	);
}

/**
 * The page around an auth panel: a centred column on the page background with
 * the brand above the card and a small muted footer below. It adds no
 * landmarks, so it can sit inside the host's own `main`.
 */
export function AuthLayout({ children, brand, footer, linkComponent, className }: AuthLayoutProps) {
	return (
		<AuthLinkContext.Provider value={linkComponent}>
			<div
				className={cn('flex min-h-dvh w-full min-w-0 flex-col items-center bg-background px-4 py-10 text-foreground sm:py-16', className)}
				data-slot="auth-layout"
			>
				<div className="flex w-full min-w-0 max-w-sm flex-1 flex-col items-center justify-center gap-6">
					{brand ? <BrandMark brand={brand} /> : null}
					{children}
					{footer ? (
						<div className="text-muted-foreground w-full min-w-0 text-pretty text-center text-xs [overflow-wrap:anywhere] [&_a]:underline [&_a]:underline-offset-4 [&_a:hover]:text-foreground">
							{footer}
						</div>
					) : null}
				</div>
			</div>
		</AuthLinkContext.Provider>
	);
}

'use client';

import * as React from 'react';
import { MailCheckIcon } from 'lucide-react';

import { Alert, AlertDescription } from '@/components/ui/alert';
import { AuthCard, AuthFailure, AuthSubmit, BackToSignIn, EmailAddress } from '@/components/ui/auth-pages/auth-card';
import type { CheckEmailPanelProps } from '@/components/ui/auth-pages/types';
import { useAuthForm } from '@/components/ui/auth-pages/use-auth-form';

function checkEmailDescription(email?: string): React.ReactNode {
	if (!email) return 'We sent you a confirmation link. Open it to confirm your address, then sign in with your password.';
	return (
		<>
			We sent a confirmation link to <EmailAddress email={email} />. Open it to confirm your address, then sign in with your
			password.
		</>
	);
}

/**
 * Tells a new account to confirm its address, then sign in with its password.
 * Sign-up renders it in place after `{ ok: true }` with `focusTitle`, so the
 * new heading is announced where the form was.
 */
export function CheckEmailPanel({
	email,
	onResend,
	links,
	title = 'Check your email',
	description,
	notice,
	linkComponent,
	className,
	focusTitle = false,
}: CheckEmailPanelProps & { focusTitle?: boolean }) {
	const form = useAuthForm({});
	const [resent, setResent] = React.useState(false);
	const trimmed = email?.trim() || undefined;

	return (
		<AuthCard
			className={className}
			description={description ?? checkEmailDescription(trimmed)}
			focusTitle={focusTitle}
			footer={links?.signIn ? <BackToSignIn href={links.signIn} /> : null}
			icon={MailCheckIcon}
			linkComponent={linkComponent}
			notice={notice}
			title={title}
		>
			<p className="text-muted-foreground text-pretty text-[13px] [overflow-wrap:anywhere]">
				The link can take a minute to arrive. If you do not see it, check your spam folder
				{onResend ? ' or send it again.' : '.'}
			</p>
			{resent ? (
				<Alert role="status" variant="success">
					<AlertDescription>
						{trimmed ? (
							<>
								We sent a new link to <EmailAddress email={trimmed} />.
							</>
						) : (
							'We sent a new link.'
						)}
					</AlertDescription>
				</Alert>
			) : null}
			<AuthFailure message={form.failure} />
			{onResend ? (
				<AuthSubmit
					label="Resend email"
					onClick={() => {
						setResent(false);
						void form.submit({ run: onResend, onSuccess: () => setResent(true) });
					}}
					pending={form.pending}
					pendingLabel="Sending…"
					type="button"
					variant="outline"
				/>
			) : null}
		</AuthCard>
	);
}

'use client';

import * as React from 'react';
import { MailCheckIcon, RotateCcwKeyIcon } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Field, FieldGroup } from '@/components/ui/field';
import { AuthCard, AuthFailure, AuthSubmit, BackToSignIn, EmailAddress } from '@/components/ui/auth-pages/auth-card';
import { EmailInput } from '@/components/ui/auth-pages/password-input';
import type { ForgotPasswordPanelProps } from '@/components/ui/auth-pages/types';
import { emailError, useAuthForm } from '@/components/ui/auth-pages/use-auth-form';

/**
 * Asks for a password reset link. On `{ ok: true }` it says a link is on its
 * way if an account exists, so the page never reveals which addresses have one.
 */
export function ForgotPasswordPanel({
	onSubmit,
	links,
	title = 'Reset your password',
	description = 'Enter the email address for your account and we will send you a link to choose a new password.',
	notice,
	linkComponent,
	className,
}: ForgotPasswordPanelProps) {
	const [sentTo, setSentTo] = React.useState<string>();
	const form = useAuthForm({ email: '' });
	const footer = links?.signIn ? <BackToSignIn href={links.signIn} /> : null;

	if (sentTo !== undefined) {
		return (
			<AuthCard
				className={className}
				description={
					<>
						If an account exists for <EmailAddress email={sentTo} />, a reset link is on its way.
					</>
				}
				focusTitle
				footer={footer}
				icon={MailCheckIcon}
				linkComponent={linkComponent}
				title="Check your email"
			>
				<p className="text-muted-foreground text-pretty text-[13px] [overflow-wrap:anywhere]">
					The link can take a minute to arrive. If you do not see it, check your spam folder.
				</p>
				<Button onClick={() => setSentTo(undefined)} type="button" variant="outline" wrap>
					Use a different email
				</Button>
			</AuthCard>
		);
	}

	const submit = (event: React.FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const trimmed = form.values.email.trim();
		void form.submit({
			validate: () => ({ email: emailError(trimmed) }),
			run: () => onSubmit({ email: trimmed }),
			onSuccess: () => setSentTo(trimmed),
			focusOnFailure: 'email',
		});
	};

	return (
		<AuthCard
			className={className}
			description={description}
			footer={footer}
			icon={RotateCcwKeyIcon}
			linkComponent={linkComponent}
			notice={notice}
			title={title}
		>
			<form className="flex min-w-0 flex-col gap-4" noValidate onSubmit={submit}>
				<FieldGroup>
					<Field label="Email address" required {...form.field('email')}>
						<EmailInput {...form.input('email')} name="email" required />
					</Field>
				</FieldGroup>
				<AuthFailure message={form.failure} />
				<AuthSubmit label="Send reset link" pending={form.pending} pendingLabel="Sending reset link…" />
			</form>
		</AuthCard>
	);
}

/**
 * Auth Pages: sign-in, sign-up, check-email, verify-email, forgot-password, and
 * reset-password panels with a page layout. Every panel takes injected handlers
 * that answer `{ ok: true }` or `{ ok: false, message }`; nothing is fetched,
 * routed, or stored here.
 */
export type {
	AuthBrand,
	AuthHandlerResult,
	AuthLayoutProps,
	AuthLinkComponent,
	AuthNotice,
	AuthPanelBase,
	AuthResult,
	CheckEmailPanelProps,
	ForgotPasswordPanelProps,
	ForgotPasswordValues,
	ResetPasswordPanelProps,
	ResetPasswordValues,
	SignInPanelProps,
	SignInValues,
	SignUpPanelProps,
	SignUpValues,
	VerifyEmailPanelProps,
} from '@/components/ui/auth-pages/types';

export { AuthLayout } from '@/components/ui/auth-pages/auth-layout';
export { SignInPanel } from '@/components/ui/auth-pages/sign-in-panel';
export { SignUpPanel } from '@/components/ui/auth-pages/sign-up-panel';
export { CheckEmailPanel } from '@/components/ui/auth-pages/check-email-panel';
export { VerifyEmailPanel } from '@/components/ui/auth-pages/verify-email-panel';
export { ForgotPasswordPanel } from '@/components/ui/auth-pages/forgot-password-panel';
export { ResetPasswordPanel } from '@/components/ui/auth-pages/reset-password-panel';
export { EmailInput, PasswordInput, type EmailInputProps, type PasswordInputProps } from '@/components/ui/auth-pages/password-input';

'use client';

import * as React from 'react';
import { EyeIcon, EyeOffIcon, LockKeyholeIcon, MailIcon } from 'lucide-react';

import { Button } from '@/components/ui/button';
import type { InputProps } from '@/components/ui/input';
import { InputGroup, InputGroupAddon, InputGroupInput } from '@/components/ui/input-group';

export type PasswordInputProps = Omit<InputProps, 'type' | 'ref'>;

/** A password input with a lock icon and a show/hide toggle. */
export const PasswordInput = React.forwardRef<HTMLInputElement, PasswordInputProps>(function PasswordInput(props, ref) {
	const [visible, setVisible] = React.useState(false);
	return (
		<InputGroup>
			<InputGroupAddon>
				<LockKeyholeIcon aria-hidden="true" />
			</InputGroupAddon>
			<InputGroupInput {...props} ref={ref} type={visible ? 'text' : 'password'} />
			<InputGroupAddon align="inline-end">
				<Button
					aria-label={visible ? 'Hide password' : 'Show password'}
					aria-pressed={visible}
					className="size-7 p-0"
					onClick={() => setVisible((value) => !value)}
					size="sm"
					type="button"
					variant="ghost"
				>
					{visible ? <EyeOffIcon aria-hidden="true" /> : <EyeIcon aria-hidden="true" />}
				</Button>
			</InputGroupAddon>
		</InputGroup>
	);
});

export type EmailInputProps = Omit<InputProps, 'type' | 'ref'>;

/** An email input with a mail icon; the password input's sibling on every form. */
export const EmailInput = React.forwardRef<HTMLInputElement, EmailInputProps>(function EmailInput(props, ref) {
	return (
		<InputGroup>
			<InputGroupAddon>
				<MailIcon aria-hidden="true" />
			</InputGroupAddon>
			<InputGroupInput autoCapitalize="none" autoComplete="email" spellCheck={false} {...props} ref={ref} type="email" />
		</InputGroup>
	);
});

'use client';

import * as React from 'react';
import { CircleCheckIcon, LockKeyholeIcon } from 'lucide-react';

import { Field, FieldGroup } from '@/components/ui/field';
import { AuthCard, AuthFailure, AuthLinkButton, AuthSubmit, BackToSignIn } from '@/components/ui/auth-pages/auth-card';
import { PasswordInput } from '@/components/ui/auth-pages/password-input';
import type { ResetPasswordPanelProps } from '@/components/ui/auth-pages/types';
import { passwordError, passwordRule, useAuthForm } from '@/components/ui/auth-pages/use-auth-form';

function confirmError(password: string, confirm: string): string | undefined {
	if (!confirm) return 'Enter the new password again.';
	if (confirm !== password) return 'The passwords do not match.';
	return undefined;
}

/** Sets a new password from a reset link: the password twice, then a way to sign in. */
export function ResetPasswordPanel({
	onSubmit,
	links,
	passwordMinLength,
	title = 'Choose a new password',
	description = 'Set a new password to finish recovering your account.',
	notice,
	linkComponent,
	className,
}: ResetPasswordPanelProps) {
	const [done, setDone] = React.useState(false);
	const form = useAuthForm({ password: '', confirm: '' });
	const { minLength, hint } = passwordRule(passwordMinLength);

	if (done) {
		return (
			<AuthCard
				className={className}
				description="Your password has been reset. You can sign in with it now."
				focusTitle
				icon={CircleCheckIcon}
				linkComponent={linkComponent}
				title="Password updated"
				tone="success"
			>
				{links?.signIn ? (
					<AuthLinkButton href={links.signIn}>
						Sign in
					</AuthLinkButton>
				) : null}
			</AuthCard>
		);
	}

	const submit = (event: React.FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const { password, confirm } = form.values;
		void form.submit({
			validate: () => ({ password: passwordError(password, minLength), confirm: confirmError(password, confirm) }),
			run: () => onSubmit({ password }),
			onSuccess: () => setDone(true),
			focusOnFailure: 'password',
		});
	};

	return (
		<AuthCard
			className={className}
			description={description}
			footer={links?.signIn ? <BackToSignIn href={links.signIn} /> : null}
			icon={LockKeyholeIcon}
			linkComponent={linkComponent}
			notice={notice}
			title={title}
		>
			<form className="flex min-w-0 flex-col gap-4" noValidate onSubmit={submit}>
				<FieldGroup>
					<Field label="New password" required {...form.field('password', hint)}>
						<PasswordInput
							{...form.input('password', Boolean(hint))}
							autoComplete="new-password"
							minLength={minLength}
							name="new-password"
							required
						/>
					</Field>
					<Field label="Confirm new password" required {...form.field('confirm')}>
						<PasswordInput
							{...form.input('confirm')}
							autoComplete="new-password"
							name="confirm-password"
							required
						/>
					</Field>
				</FieldGroup>
				<AuthFailure message={form.failure} />
				<AuthSubmit label="Reset password" pending={form.pending} pendingLabel="Resetting password…" />
			</form>
		</AuthCard>
	);
}

'use client';

import * as React from 'react';
import { KeyRoundIcon } from 'lucide-react';

import { Checkbox } from '@/components/ui/checkbox';
import { Field, FieldGroup, FieldLabel } from '@/components/ui/field';
import { AuthCard, AuthFailure, AuthLink, AuthSubmit, footerTextClass, mutedLinkClass, primaryLinkClass } from '@/components/ui/auth-pages/auth-card';
import { EmailInput, PasswordInput } from '@/components/ui/auth-pages/password-input';
import type { SignInPanelProps } from '@/components/ui/auth-pages/types';
import { emailError, passwordError, useAuthForm } from '@/components/ui/auth-pages/use-auth-form';

/** Email and password sign-in with a remember-me choice. The host navigates on `{ ok: true }`. */
export function SignInPanel({
	onSubmit,
	links,
	defaultEmail = '',
	title = 'Sign in',
	description = 'Use your account to continue to this application.',
	notice,
	linkComponent,
	className,
}: SignInPanelProps) {
	const [rememberMe, setRememberMe] = React.useState(false);
	// After `{ ok: true }` the host is navigating away; keep the button down so a second click cannot sign in twice.
	const [signedIn, setSignedIn] = React.useState(false);
	const form = useAuthForm({ email: defaultEmail, password: '' });
	const rememberId = React.useId();

	const submit = (event: React.FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const { email, password } = form.values;
		const trimmed = email.trim();
		void form.submit({
			validate: () => ({ email: emailError(trimmed), password: passwordError(password) }),
			run: () => onSubmit({ email: trimmed, password, rememberMe }),
			onSuccess: () => setSignedIn(true),
			focusOnFailure: 'password',
		});
	};

	const footer =
		links?.forgotPassword || links?.signUp ? (
			<>
				{links.forgotPassword ? (
					<AuthLink className={mutedLinkClass} href={links.forgotPassword}>
						Forgot password?
					</AuthLink>
				) : (
					<span />
				)}
				{links.signUp ? (
					<span className={footerTextClass}>
						New here?{' '}
						<AuthLink className={primaryLinkClass} href={links.signUp}>
							Create account
						</AuthLink>
					</span>
				) : null}
			</>
		) : null;

	return (
		<AuthCard
			className={className}
			description={description}
			footer={footer}
			icon={KeyRoundIcon}
			linkComponent={linkComponent}
			notice={notice}
			title={title}
		>
			<form className="flex min-w-0 flex-col gap-4" noValidate onSubmit={submit}>
				<FieldGroup>
					<Field label="Email address" required {...form.field('email')}>
						<EmailInput {...form.input('email')} name="email" required />
					</Field>
					<Field label="Password" required {...form.field('password')}>
						<PasswordInput
							{...form.input('password')}
							autoComplete="current-password"
							name="password"
							required
						/>
					</Field>
					<Field orientation="horizontal">
						<Checkbox
							checked={rememberMe}
							id={rememberId}
							name="remember-me"
							onCheckedChange={(checked) => setRememberMe(checked === true)}
						/>
						<FieldLabel htmlFor={rememberId}>Keep me signed in on this device</FieldLabel>
					</Field>
				</FieldGroup>
				<AuthFailure message={form.failure} />
				<AuthSubmit
					disabled={signedIn}
					label={signedIn ? 'Signed in' : 'Sign in'}
					pending={form.pending}
					pendingLabel="Signing in…"
				/>
			</form>
		</AuthCard>
	);
}

'use client';

import * as React from 'react';
import { UserRoundPlusIcon } from 'lucide-react';

import { Field, FieldGroup } from '@/components/ui/field';
import { AuthCard, AuthFailure, AuthLink, AuthSubmit, footerTextClass, primaryLinkClass } from '@/components/ui/auth-pages/auth-card';
import { CheckEmailPanel } from '@/components/ui/auth-pages/check-email-panel';
import { EmailInput, PasswordInput } from '@/components/ui/auth-pages/password-input';
import type { SignUpPanelProps } from '@/components/ui/auth-pages/types';
import { emailError, passwordError, passwordRule, useAuthForm } from '@/components/ui/auth-pages/use-auth-form';

/**
 * Email and password sign-up. It never expects a session: on `{ ok: true }` it
 * shows the check-email state for the address in place of the form.
 */
export function SignUpPanel({
	onSubmit,
	links,
	passwordMinLength,
	title = 'Create an account',
	description = 'Sign up with your email address and a password.',
	notice,
	linkComponent,
	className,
}: SignUpPanelProps) {
	const [sentTo, setSentTo] = React.useState<string>();
	const form = useAuthForm({ email: '', password: '' });
	const { minLength, hint } = passwordRule(passwordMinLength);

	if (sentTo !== undefined) {
		return <CheckEmailPanel className={className} email={sentTo} focusTitle linkComponent={linkComponent} links={links} />;
	}

	const submit = (event: React.FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const { email, password } = form.values;
		const trimmed = email.trim();
		void form.submit({
			validate: () => ({ email: emailError(trimmed), password: passwordError(password, minLength) }),
			run: () => onSubmit({ email: trimmed, password }),
			onSuccess: () => setSentTo(trimmed),
			focusOnFailure: 'email',
		});
	};

	const footer = links?.signIn ? (
		<span className={footerTextClass}>
			Already have an account?{' '}
			<AuthLink className={primaryLinkClass} href={links.signIn}>
				Sign in
			</AuthLink>
		</span>
	) : null;

	return (
		<AuthCard
			className={className}
			description={description}
			footer={footer}
			icon={UserRoundPlusIcon}
			linkComponent={linkComponent}
			notice={notice}
			title={title}
		>
			<form className="flex min-w-0 flex-col gap-4" noValidate onSubmit={submit}>
				<FieldGroup>
					<Field label="Email address" required {...form.field('email')}>
						<EmailInput {...form.input('email')} name="email" required />
					</Field>
					<Field label="Password" required {...form.field('password', hint)}>
						<PasswordInput
							{...form.input('password', Boolean(hint))}
							autoComplete="new-password"
							minLength={minLength}
							name="password"
							required
						/>
					</Field>
				</FieldGroup>
				<AuthFailure message={form.failure} />
				<AuthSubmit label="Create account" pending={form.pending} pendingLabel="Creating account…" />
			</form>
		</AuthCard>
	);
}

import type * as React from 'react';

/** What every auth handler answers. A failure message is shown to the person as written. */
export type AuthResult = { ok: true } | { ok: false; message: string };

/** Handlers may answer synchronously or with a promise. */
export type AuthHandlerResult = AuthResult | Promise<AuthResult>;

/**
 * The link a host renders for in-app navigation. Same shape as resource-kit's
 * `ResourceRouter.Link`, so one router link can be passed to both.
 */
export type AuthLinkComponent = React.ComponentType<{
	href: string;
	className?: string;
	children: React.ReactNode;
}>;

/** A message the host shows above a panel, such as "Your session expired". */
export type AuthNotice = { tone: 'info' | 'success' | 'error'; message: React.ReactNode };

export type AuthPanelBase = {
	/** Replaces the panel heading (the first state of the panel). */
	title?: React.ReactNode;
	/** Replaces the line under the heading (the first state of the panel). */
	description?: React.ReactNode;
	notice?: AuthNotice;
	/** Renders the panel's links. Falls back to the `AuthLayout` link, then to a plain `<a href>`. */
	linkComponent?: AuthLinkComponent;
	className?: string;
};

export type SignInValues = { email: string; password: string; rememberMe: boolean };

export type SignInPanelProps = AuthPanelBase & {
	onSubmit(values: SignInValues): AuthHandlerResult;
	links?: { signUp?: string; forgotPassword?: string };
	defaultEmail?: string;
};

export type SignUpValues = { email: string; password: string };

export type SignUpPanelProps = AuthPanelBase & {
	/** On `{ ok: true }` the panel shows the check-email state for the address, unless the host navigated away. */
	onSubmit(values: SignUpValues): AuthHandlerResult;
	links?: { signIn?: string };
	/** Defaults to 8. */
	passwordMinLength?: number;
};

export type CheckEmailPanelProps = AuthPanelBase & {
	email?: string;
	/** Shows a resend button when given. */
	onResend?(): AuthHandlerResult;
	links?: { signIn?: string };
};

export type VerifyEmailPanelProps = AuthPanelBase & {
	/** Called once when the panel mounts, and again from "Try again" after a failure. */
	onVerify(): AuthHandlerResult;
	links?: { signIn?: string; continue?: string };
};

export type ForgotPasswordValues = { email: string };

export type ForgotPasswordPanelProps = AuthPanelBase & {
	/** On `{ ok: true }` the panel shows a neutral message that never says whether the account exists. */
	onSubmit(values: ForgotPasswordValues): AuthHandlerResult;
	links?: { signIn?: string };
};

export type ResetPasswordValues = { password: string };

export type ResetPasswordPanelProps = AuthPanelBase & {
	onSubmit(values: ResetPasswordValues): AuthHandlerResult;
	links?: { signIn?: string };
	/** Defaults to 8. */
	passwordMinLength?: number;
};

export type AuthBrand = { name: React.ReactNode; logo?: React.ReactNode; href?: string };

export type AuthLayoutProps = {
	children: React.ReactNode;
	brand?: AuthBrand;
	footer?: React.ReactNode;
	/** Used for the brand link and inherited by every panel inside the layout. */
	linkComponent?: AuthLinkComponent;
	className?: string;
};

'use client';

import * as React from 'react';

import type { AuthHandlerResult, AuthResult } from '@/components/ui/auth-pages/types';

/** Shown for a handler that throws or answers with something that is not an `AuthResult`. */
export const AUTH_GENERIC_ERROR = 'Something went wrong. Try again.';

export const DEFAULT_PASSWORD_MIN_LENGTH = 8;

// A shape check only: it catches a missing @ or a stray space, and leaves the
// real decision to the server, so `name@localhost` still gets through.
const EMAIL_SHAPE = /^[^\s@]+@[^\s@]+$/;

export type AuthFieldErrors<K extends string> = Partial<Record<K, string>>;

export function emailError(email: string): string | undefined {
	if (!email) return 'Enter an email address.';
	if (!EMAIL_SHAPE.test(email)) return 'Enter a valid email address, like name@example.com.';
	return undefined;
}

export function passwordError(password: string, minLength = 1): string | undefined {
	if (!password) return 'Enter a password.';
	if (password.length < minLength) return `Password must be at least ${minLength} characters.`;
	return undefined;
}

/** The minimum length for a new password (a panel's `passwordMinLength`, default 8) and the field hint that states it. */
export function passwordRule(value: number | undefined): { minLength: number; hint?: string } {
	const minLength =
		value === undefined || !Number.isFinite(value) ? DEFAULT_PASSWORD_MIN_LENGTH : Math.max(1, Math.floor(value));
	return { minLength, hint: minLength > 1 ? `Use at least ${minLength} characters.` : undefined };
}

function failureMessage(result: unknown): string | undefined {
	if (!result || typeof result !== 'object') return AUTH_GENERIC_ERROR;
	const { ok, message } = result as Partial<{ ok: boolean; message: unknown }>;
	if (ok === true) return undefined;
	return ok === false && typeof message === 'string' && message.trim() ? message : AUTH_GENERIC_ERROR;
}

type SubmitOptions<K extends string> = {
	/** Field errors to show; the handler only runs when this returns none. */
	validate?: () => AuthFieldErrors<K>;
	run: () => AuthHandlerResult;
	/** Runs on `{ ok: true }`, only while the panel is still mounted. */
	onSuccess?: () => void;
	/** The field that takes focus when the handler fails, so the alert is read next to it. */
	focusOnFailure?: K;
};

/**
 * Field values, submit, validation, and pending state shared by every auth
 * panel: field errors wired to `aria-invalid`/`aria-describedby` with focus on
 * the first invalid field (in the key order of `initial`), one call at a time,
 * and a failure message for the alert.
 */
export function useAuthForm<K extends string>(initial: Record<K, string>) {
	const baseId = React.useId();
	const [values, setValues] = React.useState(initial);
	const [errors, setErrors] = React.useState<AuthFieldErrors<K>>({});
	const [pending, setPending] = React.useState(false);
	const [failure, setFailure] = React.useState<string>();
	const inputs = React.useRef<Partial<Record<K, HTMLInputElement | null>>>({});
	const running = React.useRef(false);
	const mounted = React.useRef(false);

	React.useEffect(() => {
		mounted.current = true;
		return () => {
			mounted.current = false;
		};
	}, []);

	const ids = (name: K) => ({
		input: `${baseId}-${name}`,
		error: `${baseId}-${name}-error`,
		description: `${baseId}-${name}-description`,
	});

	/** Props for the `Field` around an input. */
	const field = (name: K, description?: string) => ({
		htmlFor: ids(name).input,
		error: errors[name],
		errorId: ids(name).error,
		description,
		descriptionId: description ? ids(name).description : undefined,
	});

	/** Props for the input itself, value included; typing clears the field's error. Pass `described` when its `Field` has a description. */
	const input = (name: K, described = false) => {
		const describedBy = [described && ids(name).description, errors[name] && ids(name).error].filter(Boolean).join(' ');
		return {
			id: ids(name).input,
			ref: (node: HTMLInputElement | null) => {
				inputs.current[name] = node;
			},
			value: values[name],
			onChange: (event: React.ChangeEvent<HTMLInputElement>) => {
				const value = event.currentTarget.value;
				setValues((current) => ({ ...current, [name]: value }));
				setErrors((current) => (current[name] ? { ...current, [name]: undefined } : current));
			},
			'aria-invalid': errors[name] ? true : undefined,
			'aria-describedby': describedBy || undefined,
		};
	};

	const submit = async ({ validate, run, onSuccess, focusOnFailure }: SubmitOptions<K>) => {
		if (running.current) return;
		const next: AuthFieldErrors<K> = validate?.() ?? {};
		setErrors(next);
		setFailure(undefined);
		const firstInvalid = (Object.keys(values) as K[]).find((name) => next[name]);
		if (firstInvalid) {
			inputs.current[firstInvalid]?.focus();
			return;
		}

		running.current = true;
		setPending(true);
		let result: AuthResult | undefined;
		try {
			result = await run();
		} catch {
			result = undefined;
		}
		running.current = false;
		if (!mounted.current) return;
		setPending(false);
		const message = failureMessage(result);
		if (message === undefined) {
			onSuccess?.();
			return;
		}
		setFailure(message);
		if (focusOnFailure) inputs.current[focusOnFailure]?.focus();
	};

	return { values, pending, failure, field, input, submit };
}

'use client';

import * as React from 'react';
import { CircleCheckIcon, MailWarningIcon, RotateCcwIcon } from 'lucide-react';

import { AuthCard, AuthFailure, AuthLinkButton, AuthSubmit, BackToSignIn } from '@/components/ui/auth-pages/auth-card';
import type { VerifyEmailPanelProps } from '@/components/ui/auth-pages/types';
import { useAuthForm } from '@/components/ui/auth-pages/use-auth-form';

/**
 * Confirms an email address from a verification link. It calls `onVerify` once
 * on mount (StrictMode's second effect run does not call it again), then shows
 * the result: a link onward, or the failure with "Try again".
 */
export function VerifyEmailPanel({
	onVerify,
	links,
	title = 'Verifying your email',
	description = 'This takes a moment. Keep this page open.',
	notice,
	linkComponent,
	className,
}: VerifyEmailPanelProps) {
	const form = useAuthForm({});
	const [verified, setVerified] = React.useState(false);
	const started = React.useRef(false);

	const verify = () => {
		void form.submit({ run: onVerify, onSuccess: () => setVerified(true) });
	};

	// Mount only: the first render's `verify` is enough, and "Try again" uses the current one.
	React.useEffect(() => {
		if (started.current) return;
		started.current = true;
		verify();
	}, []);

	const footer = links?.signIn ? <BackToSignIn href={links.signIn} /> : null;
	const onward = links?.continue ?? links?.signIn;

	// Each state is its own card (`key`), so the result heading takes focus and is announced when it replaces the spinner.
	if (verified) {
		return (
			<AuthCard
				className={className}
				description={links?.continue ? 'Your email address is confirmed.' : 'Your email address is confirmed. You can sign in now.'}
				focusTitle
				icon={CircleCheckIcon}
				key="verified"
				linkComponent={linkComponent}
				notice={notice}
				title="Email verified"
				tone="success"
			>
				{onward ? (
					<AuthLinkButton href={onward}>
						{links?.continue ? 'Continue' : 'Sign in'}
					</AuthLinkButton>
				) : null}
			</AuthCard>
		);
	}

	if (form.failure) {
		return (
			<AuthCard
				className={className}
				description="The link may have expired or already been used."
				focusTitle
				footer={footer}
				icon={MailWarningIcon}
				key="failed"
				linkComponent={linkComponent}
				notice={notice}
				title="We could not verify your email"
				tone="destructive"
			>
				<AuthFailure message={form.failure} />
				<AuthSubmit
					label={
						<>
							<RotateCcwIcon aria-hidden="true" />
							Try again
						</>
					}
					onClick={verify}
					pending={form.pending}
					pendingLabel="Verifying…"
					type="button"
				/>
			</AuthCard>
		);
	}

	return (
		<AuthCard
			className={className}
			description={description}
			footer={footer}
			icon="spinner"
			key="verifying"
			linkComponent={linkComponent}
			notice={notice}
			title={title}
		/>
	);
}
